/* From Uiverse.io by G4b413l - Tags: loader */
.__UIV_SCOPE__ .spinner {
  position: relative;
  width: 60px;
  height: 60px;
  border-radius: 50%;
}

.__UIV_SCOPE__ .spinner::before,
.__UIV_SCOPE__ .spinner::after {
  content: "";
  position: absolute;
  border-radius: inherit;
}

.__UIV_SCOPE__ .spinner::before {
  width: 100%;
  height: 100%;
  background-image: linear-gradient(0deg, #ff00cc 0%, #212121 50%);
  animation: spin .5s infinite linear;
}

.__UIV_SCOPE__ .spinner::after {
  width: 85%;
  height: 85%;
  background-color: #212121;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
